var STRENGTH_SYMBOLS=" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";
var STRENGTH_COMMON=["password","123456","12345678","qwerty","abc123","admin","welcome","iloveyou","111111","letmein"];
function strengthClasses(pw){
  var c={lower:false,upper:false,digit:false,symbol:false};
  for(var i=0;i<pw.length;i++){ var ch=pw[i];
    if(ch>='a'&&ch<='z') c.lower=true;
    else if(ch>='A'&&ch<='Z') c.upper=true;
    else if(ch>='0'&&ch<='9') c.digit=true;
    else c.symbol=true;
  }
  return c;
}
function strengthCharset(pw){
  var c=strengthClasses(pw), n=0;
  if(c.lower) n+=26; if(c.upper) n+=26; if(c.digit) n+=10; if(c.symbol) n+=STRENGTH_SYMBOLS.length;
  return n;
}
function strengthEntropy(pw){
  var cs=strengthCharset(pw); if(!cs) return 0;
  return pw.length*Math.log(cs)/Math.log(2);
}
function strengthScore(ent){
  if(ent<28) return 0; if(ent<36) return 1; if(ent<60) return 2; if(ent<120) return 3; return 4;
}
function strengthPenalty(pw){
  var w=[];
  if(pw.length<8) w.push('长度不足 8 位');
  if(/^(.)\1+$/.test(pw)) w.push('全部字符重复');
  if(/(.)\1{2,}/.test(pw)) w.push('存在连续重复字符');
  var low=pw.toLowerCase();
  if(STRENGTH_COMMON.indexOf(low)>=0) w.push('命中常见弱口令字典');
  if(/^[a-z]+$/.test(low) && low.length>=3){
    var seq='abcdefghijklmnopqrstuvwxyz', ok=false;
    for(var i=0;i+low.length<=seq.length;i++){ if(seq.substr(i,low.length)===low){ok=true;break;} }
    if(ok) w.push('连续字母序列');
  }
  return w;
}
function strengthCrack(ent){
  var sps=1e9; var sec=Math.pow(2,ent)/sps;
  if(sec<1) return '<1 秒';
  if(sec<60) return Math.round(sec)+' 秒';
  if(sec<3600) return Math.round(sec/60)+' 分钟';
  if(sec<86400) return Math.round(sec/3600)+' 小时';
  if(sec<31536000) return Math.round(sec/86400)+' 天';
  if(sec<31536000*100) return Math.round(sec/31536000)+' 年';
  return (sec/31536000).toExponential(1)+' 年';
}
function strengthAnalyze(pw){
  if(pw==='') return { empty:true };
  var ent=strengthEntropy(pw);
  var pen=strengthPenalty(pw);
  var score=strengthScore(ent);
  if(pen.length) score=Math.max(0,score-1);
  return { length:pw.length, charset:strengthCharset(pw), entropy:ent, score:score,
    crack:strengthCrack(ent), warnings:pen };
}
function strengthRand(len){
  len=len||16; var cs='abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789!@#$%&*';
  var s=''; for(var i=0;i<len;i++) s+=cs[Math.floor(Math.random()*cs.length)]; return s;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { strengthClasses:strengthClasses, strengthCharset:strengthCharset,
    strengthEntropy:strengthEntropy, strengthScore:strengthScore, strengthPenalty:strengthPenalty,
    strengthCrack:strengthCrack, strengthAnalyze:strengthAnalyze, strengthRand:strengthRand,
    STRENGTH_SYMBOLS:STRENGTH_SYMBOLS };
}
if (typeof window !== 'undefined') {
  window.StrengthForgePure = { strengthClasses:strengthClasses, strengthCharset:strengthCharset,
    strengthEntropy:strengthEntropy, strengthScore:strengthScore, strengthPenalty:strengthPenalty,
    strengthCrack:strengthCrack, strengthAnalyze:strengthAnalyze, strengthRand:strengthRand,
    STRENGTH_SYMBOLS:STRENGTH_SYMBOLS };
}
